def clamp(value, lo, hi):
    if value < lo:
        return lo
    if value > hi:
        return hi
    return value

def is_palindrome(s):
    cleaned = ''.join(ch.lower() for ch in s if ch.isalnum())
    return cleaned == cleaned[::-1]

def average(nums):
    if not nums:
        return None
    return sum(nums) / float(len(nums))

def safe_divide(a, b):
    if b == 0:
        raise ValueError('division by zero')
    return a / b

from typing import List, Union

NestedIntList = List[Union[int, "NestedIntList"]]


def flatten(nested):
    result = []

    def _flatten(value):
        if isinstance(value, list):
            for item in value:
                _flatten(item)
        else:
            result.append(value)

    _flatten(nested)
    return result

import re
from collections import defaultdict


def most_common_word(text):
    words = [match.group(0).lower() for match in re.finditer(r"[^\W_]+", text, flags=re.UNICODE)]
    if not words:
        return ""

    counts = defaultdict(int)
    first_pos = {}

    for index, word in enumerate(words):
        counts[word] += 1
        if word not in first_pos:
            first_pos[word] = index

    best_word = None
    best_count = -1
    best_first = len(words)

    for word, count in counts.items():
        pos = first_pos[word]
        if count > best_count or (count == best_count and pos < best_first):
            best_word = word
            best_count = count
            best_first = pos

    return best_word

import re

_DURATION_RE = re.compile(r"^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$")


def parse_duration(s):
    match = _DURATION_RE.fullmatch(s)
    if not match:
        raise ValueError(f"invalid duration string: {s!r}")

    hours, minutes, seconds = match.groups()
    total = 0
    if hours is not None:
        total += int(hours) * 3600
    if minutes is not None:
        total += int(minutes) * 60
    if seconds is not None:
        total += int(seconds)
    return total
